import { z } from "zod";
import { defineTool } from "../../core/define-tool";
import { ToolTier } from "../../types";
import { qrCodeGenerator } from "./qr-code-generator";

const inputSchema = z.object({
  firstName: z.string().min(1).describe("First name"),
  lastName: z.string().default("").describe("Last name"),
  organization: z.string().default("").describe("Organization/Company"),
  title: z.string().default("").describe("Job title"),
  phone: z.string().default("").describe("Phone number"),
  email: z.string().default("").describe("Email address"),
  website: z.string().default("").describe("Website URL"),
  address: z
    .object({
      street: z.string().default("").describe("Street address"),
      city: z.string().default("").describe("City"),
      state: z.string().default("").describe("State/Province"),
      zip: z.string().default("").describe("Postal code"),
      country: z.string().default("").describe("Country"),
    })
    .prefault({})
    .describe("Physical address"),
  note: z.string().default("").describe("Additional notes"),
  size: z
    .number()
    .min(100)
    .max(1000)
    .default(200)
    .describe("QR code size in pixels"),
  errorCorrection: z
    .enum(["L", "M", "Q", "H"])
    .default("M")
    .describe("Error correction level"),
});

const outputSchema = z.object({
  output: z.string().describe("vCard QR code as SVG string"),
});

type Input = z.infer<typeof inputSchema>;
type Output = z.infer<typeof outputSchema>;

function execute(input: Input): Output {
  // Build vCard string
  const lines: string[] = [];
  lines.push("BEGIN:VCARD");
  lines.push("VERSION:3.0");
  lines.push(`N:${input.lastName};${input.firstName};;;`);
  lines.push(
    `FN:${input.firstName}${input.lastName ? " " + input.lastName : ""}`
  );

  if (input.organization) {
    lines.push(`ORG:${input.organization}`);
  }
  if (input.title) {
    lines.push(`TITLE:${input.title}`);
  }
  if (input.phone) {
    lines.push(`TEL;TYPE=CELL:${input.phone}`);
  }
  if (input.email) {
    lines.push(`EMAIL:${input.email}`);
  }
  if (input.website) {
    lines.push(`URL:${input.website}`);
  }

  const addr = input.address;
  if (
    addr &&
    (addr.street || addr.city || addr.state || addr.zip || addr.country)
  ) {
    lines.push(
      `ADR;TYPE=WORK:;;${addr.street || ""};${addr.city || ""};${addr.state || ""};${addr.zip || ""};${addr.country || ""}`
    );
  }

  if (input.note) {
    lines.push(`NOTE:${input.note}`);
  }

  lines.push("END:VCARD");

  const vcard = lines.join("\n");

  // Generate the QR code SVG using the core QR code generator
  const result = qrCodeGenerator.execute({
    text: vcard,
    size: input.size,
    errorCorrection: input.errorCorrection,
    darkColor: "#000000",
    lightColor: "#ffffff",
  }) as { output: string };

  return { output: result.output };
}

